import { useEffect, useId, useMemo, useRef, useState } from 'react';
import { Activity, AlertTriangle, Bell, BookOpen, Bot, CheckCircle2, ChevronRight, Copy, Database, Gauge, History, Home, Library, Mic, PauseCircle, Play, RefreshCw, Settings, SlidersHorizontal, Sparkles, Square, TestTube2, Wand2, X } from 'lucide-react';
import { LOOPBACK_HOST, validateServicePreferences } from '../electron/service-contract';
import type { ServiceDiagnostic, ServiceFailure, ServicePreferences, ServiceSnapshot } from '../electron/service-contract';
import { demoEngines, demoJobs, demoProfiles, demoReferences, demoSettings, demoVoices, nowIso } from './demoData';
import type { ApplicationSettings, AudioReference, EmotionalMode, Engine, GenerationJob, InterpretationPlan, JobStatus, Voice } from './types';

type Screen = 'production'|'voices'|'clone'|'tts'|'emotional'|'engines'|'history'|'settings';
type Toast = { id:string; kind:'success'|'warning'|'error'|'info'; text:string };
type AppState = { voices: Voice[]; engines: Engine[]; references: AudioReference[]; jobs: GenerationJob[]; settings: ApplicationSettings; profiles: typeof demoProfiles };
type CreateJobOptions = Partial<Pick<GenerationJob['request'],'emotionalMode'|'emotionalDirectorEnabled'|'engineParameters'|'comparisonSide'|'comparisonId'|'interpretationPlanId'|'emotionalProfileId'>> & { versionOverride?: { id:string; label:string; engineId:string } };
const STORAGE_KEY = 'voice-studio-demo-state-v1';

const nav: Array<{id:Screen; label:string; icon: typeof Home}> = [
  {id:'production',label:'Producción',icon:Home},{id:'voices',label:'Biblioteca de voces',icon:Library},{id:'clone',label:'Clonar voz',icon:Mic},{id:'tts',label:'Generación TTS',icon:TestTube2},{id:'emotional',label:'Director emocional',icon:Wand2},{id:'engines',label:'Motores',icon:Bot},{id:'history',label:'Historial y actividad',icon:History},{id:'settings',label:'Ajustes',icon:Settings}
];
const initialState = (): AppState => ({ voices: demoVoices, engines: demoEngines, references: demoReferences, jobs: demoJobs, settings: demoSettings, profiles: demoProfiles });

function loadState(): AppState {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    const loaded = raw ? JSON.parse(raw) as AppState : initialState();
    const storedPreferences = loaded.settings?.service;
    let preferences: ReturnType<typeof validateServicePreferences>;

    try {
      preferences = validateServicePreferences(storedPreferences ?? demoSettings.service);
    } catch {
      const candidate = (storedPreferences && typeof storedPreferences === 'object'
        ? storedPreferences
        : {}) as Partial<ReturnType<typeof validateServicePreferences>>;
      let port = demoSettings.service.port;

      try {
        port = validateServicePreferences({
          port: candidate.port,
          autoStart: true,
          keepRunningOnClose: true,
        }).port;
      } catch {
        // An invalid persisted port falls back without discarding other app data.
      }

      preferences = validateServicePreferences({
        port,
        autoStart: typeof candidate.autoStart === 'boolean'
          ? candidate.autoStart
          : demoSettings.service.autoStart,
        keepRunningOnClose: typeof candidate.keepRunningOnClose === 'boolean'
          ? candidate.keepRunningOnClose
          : demoSettings.service.keepRunningOnClose,
      });
    }

    return {
      ...loaded,
      settings: {
        ...loaded.settings,
        service: { ...preferences, status: 'stopped', host: LOOPBACK_HOST },
      },
    };
  } catch {
    return initialState();
  }
}
function cls(...v: Array<string|false|undefined>) { return v.filter(Boolean).join(' '); }
function fmt(iso?: string) { return iso ? new Date(iso).toLocaleString('es-ES', { hour:'2-digit', minute:'2-digit', day:'2-digit', month:'2-digit' }) : '—'; }
function statusLabel(s: JobStatus) { return ({queued:'En cola',processing:'Procesando',completed:'Completada',error:'Error',cancelled:'Cancelada'} as const)[s]; }
function getVoice(st:AppState,id:string){return st.voices.find(v=>v.id===id)!}
function getVersion(v:Voice,id:string){return v.versions.find(x=>x.id===id) ?? v.versions[0]}
function getEngine(st:AppState,id:string){return st.engines.find(e=>e.id===id)!}
function defaultEngineParameters(engine:Engine){ return Object.fromEntries(engine.capabilities.dynamicSettings.map(s=>[s.key,s.defaultValue])) as Record<string,string|number|boolean>; }
function compatibilityFor(versionEngineId:string, engine:Engine){ return engine.status!=='available' ? 'engine_unavailable' : versionEngineId!==engine.id ? 'different_provider' : 'compatible'; }
function validationError(origin:GenerationJob['request']['origin'], voice:Voice, versionEngineId:string, engine:Engine){ if(origin==='Streamer.bot demo' && !voice.enabledForStreamerBot) return 'Voz deshabilitada para solicitudes externas.'; if(engine.status!=='available') return 'Motor no disponible o no configurado.'; if(versionEngineId!==engine.id) return 'Motor incompatible con la referencia activa de la voz.'; return undefined; }

export function App(){
  const [state,setState]=useState<AppState>(loadState);
  const [screen,setScreen]=useState<Screen>('production');
  const [toasts,setToasts]=useState<Toast[]>([]);
  const [diagJob,setDiagJob]=useState<GenerationJob|null>(null);
  const [selectedServiceDiagnostic,setSelectedServiceDiagnostic]=useState<ServiceFailure|ServiceDiagnostic|null>(null);
  const [serviceSnapshot,setServiceSnapshot]=useState<ServiceSnapshot|null>(null);
  const [serviceAvailable,setServiceAvailable]=useState<boolean|null>(null);
  const [serviceDiagnostics,setServiceDiagnostics]=useState<ServiceDiagnostic[]>([]);
  const [serviceDiagnosticsWarning,setServiceDiagnosticsWarning]=useState<string|null>(null);
  const [confirmEngine,setConfirmEngine]=useState<string|null>(null);
  const [selectedJob,setSelectedJob]=useState<GenerationJob|null>(null);
  const serviceQueue=useRef<Promise<void>>(Promise.resolve());
  const appliedServicePreferences=useRef<ServicePreferences>(validateServicePreferences(state.settings.service));
  const notify=(text:string,kind:Toast['kind']='info')=>{ const id=crypto.randomUUID(); setToasts(t=>[{id,text,kind},...t].slice(0,4)); setTimeout(()=>setToasts(t=>t.filter(x=>x.id!==id)),3600); };
  const enqueueService=<T,>(operation:()=>Promise<T>):Promise<T>=>{ const pending=serviceQueue.current.then(operation,operation); serviceQueue.current=pending.then(()=>undefined,()=>undefined); return pending; };
  const refreshServiceDiagnostics=async(bridge:NonNullable<typeof window.voiceStudio>['service'])=>{ try { const items=await bridge.getDiagnostics(); setServiceDiagnostics(items); setServiceDiagnosticsWarning(null); } catch(error) { setServiceDiagnosticsWarning(error instanceof Error?error.message:'No se pudieron obtener los diagnósticos del servicio.'); } };
  useEffect(()=>{ const persisted={...state,settings:{...state.settings,service:{...state.settings.service,status:'stopped',host:LOOPBACK_HOST}}}; localStorage.setItem(STORAGE_KEY,JSON.stringify(persisted)); },[state]);
  useEffect(()=>{ if(state.jobs.some(j=>j.status==='processing')) return; const next=[...state.jobs].filter(j=>j.status==='queued').sort((a,b)=>a.order-b.order)[0]; if(!next) return; const timer=window.setTimeout(()=>setState(s=>({...s,jobs:s.jobs.map(j=>j.id===next.id&&j.status==='queued'?{...j,status:'processing',startedAt:nowIso(),events:[...j.events,{id:`evt-${j.id}-proc`,jobId:j.id,at:nowIso(),stage:'Procesamiento',summary:'Procesamiento demo iniciado respetando el orden de cola',technicalDetail:'Estado simulado. Sólo se procesa un trabajo a la vez.',level:'info',simulated:true}]}:j)})),300); return ()=>window.clearTimeout(timer); },[state.jobs]);
  useEffect(()=>{ const active=state.jobs.find(j=>j.status==='processing'); if(!active) return; const timer=window.setTimeout(()=>setState(s=>({...s,jobs:s.jobs.map(j=>{ if(j.id!==active.id||j.status!=='processing') return j; const voice=s.voices.find(v=>v.id===j.request.voiceId); const version=voice?.versions.find(v=>v.id===j.request.versionId); const engine=s.engines.find(e=>e.id===j.request.engineId); const versionEngineId=version?.engineId??j.snapshot.versionEngineId; const error=j.request.simulatedError||(voice&&engine&&versionEngineId?validationError(j.request.origin,voice,versionEngineId,engine):'La configuración del trabajo ya no está disponible.'); return finishJob(j,error); })})),1400); return ()=>window.clearTimeout(timer); },[state.jobs,state.voices,state.engines]);
  useEffect(()=>{ const bridge=window.voiceStudio?.service; if(!bridge){setServiceAvailable(false);return;} let mounted=true; const receive=(snapshot:ServiceSnapshot)=>{ if(!mounted)return; setServiceSnapshot(snapshot); if(snapshot.status==='error') void refreshServiceDiagnostics(bridge); }; const unsubscribe=bridge.onStateChange(receive); const initialize=async()=>{ try { const current=await enqueueService(()=>bridge.getState()); if(!mounted)return; receive(current); const preferences=validateServicePreferences(state.settings.service); const configured=await enqueueService(()=>bridge.configure(preferences)); receive(configured); setServiceAvailable(true); } catch(error) { if(mounted){setServiceAvailable(false);notify(error instanceof Error?error.message:'No se pudo conectar con el host de escritorio.','error');} return; } void refreshServiceDiagnostics(bridge); }; void initialize(); return ()=>{mounted=false;unsubscribe();}; },[]);
  const updateSettings=(fn:(s:ApplicationSettings)=>ApplicationSettings)=>setState(s=>({...s,settings:fn(s.settings)}));
  const updateServicePreferences=async(change:Partial<ServicePreferences>)=>{ const bridge=window.voiceStudio?.service; if(!bridge){notify('El host de escritorio no está disponible.','error');return;} try { const {snapshot,preferences}=await enqueueService(async()=>{ const preferences=validateServicePreferences({...appliedServicePreferences.current,...change}); const snapshot=await bridge.configure(preferences); appliedServicePreferences.current=preferences; return {snapshot,preferences}; }); setServiceSnapshot(snapshot); setState(current=>({...current,settings:{...current.settings,service:{...preferences,status:'stopped',host:LOOPBACK_HOST}}})); if(snapshot.status==='error'){void refreshServiceDiagnostics(bridge);notify(snapshot.lastError?.summary??'Error al configurar el servicio local.','error');} else notify('Preferencias del servicio aplicadas.','success'); } catch(error) { notify(error instanceof Error?error.message:'No se pudieron aplicar las preferencias del servicio.','error'); } };
  const runServiceCommand=async(command:'start'|'stop'|'restart')=>{ const bridge=window.voiceStudio?.service; if(!bridge){notify('El host de escritorio no está disponible.','error');return;} try { const snapshot=await enqueueService(()=>bridge[command]()); setServiceSnapshot(snapshot); if(snapshot.status==='error'){void refreshServiceDiagnostics(bridge);notify(snapshot.lastError?.summary??'Falló la operación del servicio local.','error');} else notify(command==='restart'?'Servicio local reiniciado.':command==='start'?'Servicio local iniciado.':'Servicio local detenido.','success'); } catch(error) { notify(error instanceof Error?error.message:'No se pudo completar la operación del servicio.','error'); } };
  const toggleService=()=>runServiceCommand(serviceSnapshot?.status==='active'?'stop':'start');
  const restartService=()=>runServiceCommand('restart');
  const resetDemo=()=>setState(current=>{const fresh=initialState();return {...fresh,settings:{...fresh.settings,service:{...current.settings.service,status:'stopped',host:LOOPBACK_HOST}}};});
  const serviceStatus:ApplicationSettings['service']['status']=serviceAvailable===null?'connecting':serviceAvailable?(serviceSnapshot?.status??'stopped'):'unavailable';
  const viewState=useMemo(()=>({...state,settings:{...state.settings,service:{...state.settings.service,status:serviceStatus,host:serviceSnapshot?.host??LOOPBACK_HOST,port:serviceSnapshot?.port??state.settings.service.port}}}),[state,serviceAvailable,serviceSnapshot,serviceStatus]);
  const serviceFailure:ServiceFailure|null=serviceSnapshot?.lastError??serviceDiagnostics[0]??null;
  const toggleVoice=(id:string)=>setState(s=>({...s,voices:s.voices.map(v=>v.id===id?{...v,enabledForStreamerBot:!v.enabledForStreamerBot}:v)}));
  const setActiveVersion=(voiceId:string,versionId:string)=>setState(s=>({...s,voices:s.voices.map(v=>v.id===voiceId?{...v,activeVersionId:versionId}:v)}));
  const createJob=(origin:GenerationJob['request']['origin'], voiceId:string, versionId:string, engineId:string, text:string, forceError?:string, options?:CreateJobOptions)=>{
    const id=`JOB-${crypto.randomUUID().slice(0,8).toUpperCase()}`;
    setState(s=>{ const voice=getVoice(s,voiceId); const version=options?.versionOverride??getVersion(voice,versionId); const engine=getEngine(s,engineId); const params=options?.engineParameters??defaultEngineParameters(engine); const mode=options?.emotionalMode??'literal'; const directorEnabled=options?.emotionalDirectorEnabled??s.settings.production.emotionalDirectorEnabled; const compatibility=compatibilityFor(version.engineId,engine); const order=Math.max(0,...s.jobs.map(j=>j.order))+1; const job:GenerationJob={ id, order, request:{id:`REQ-${id}`,origin,voiceId,versionId:version.id,engineId,originalText:text,emotionalMode:mode,emotionalDirectorEnabled:directorEnabled,createdAt:nowIso(),engineParameters:params,emotionalProfileId:options?.emotionalProfileId??s.settings.production.emotionalProfileId,interpretationPlanId:options?.interpretationPlanId,comparisonSide:options?.comparisonSide,comparisonId:options?.comparisonId,simulatedError:forceError}, status:'queued', snapshot:{voiceName:voice.displayName,versionLabel:version.label,versionEngineId:version.engineId,engineName:engine.name,productionEngineId:s.settings.production.ttsEngineId,activeVersionIdAtStart:voice.activeVersionId,emotionalMode:mode,emotionalDirectorEnabled:directorEnabled,engineParameters:params,emotionalProfileId:options?.emotionalProfileId??s.settings.production.emotionalProfileId,compatibility}, events:[{id:`evt-${id}-queued`,jobId:id,at:nowIso(),stage:'Recepción',summary:'Solicitud demo recibida y colocada al final de la cola',technicalDetail:'Evento simulado. No se invocó ningún servicio real.',level:'info',simulated:true}] }; return {...s,jobs:[job,...s.jobs]}; });
    notify(`Solicitud ${id} agregada a la cola${options?.comparisonSide?` · lado ${options.comparisonSide}`:''}`,'info');
  };
  const applyProductionEngine=(engineId:string)=>{ updateSettings(s=>({...s,production:{...s.production,ttsEngineId:engineId}})); setConfirmEngine(null); notify('Motor de producción actualizado en modo demo','success'); };
  const value={state:viewState,setState,notify,toggleVoice,setActiveVersion,createJob,setDiagJob,setConfirmEngine,setSelectedJob,applyProductionEngine};
  const current=nav.find(n=>n.id===screen)!;
  return <div className="app-shell">
    <aside className="sidebar"><div className="brand"><div className="brand-mark">VS</div><div><strong>Voice Studio</strong><span>Modo demostración</span></div></div><nav>{nav.map(item=>{const Icon=item.icon;return <button key={item.id} onClick={()=>setScreen(item.id)} className={cls('nav-item',screen===item.id&&'active')}><Icon size={18}/><span>{item.label}</span></button>})}</nav><div className="sidebar-note"><Sparkles size={16}/> Servicio HTTP local real; voces, motores y trabajos siguen en demo.</div></aside>
    <main className="main"><Topbar state={viewState} toggleService={toggleService} reset={()=>{resetDemo();notify('Datos de demostración restaurados','success')}} openDiag={()=>setDiagJob(state.jobs.find(j=>j.status==='error')??null)} serviceAvailable={serviceAvailable} openServiceDiagnostic={()=>{if(serviceFailure)setSelectedServiceDiagnostic(serviceFailure)}} />
      <section className="content"><div className="page-title"><div><p>{current.label}</p><h1>{current.label}</h1></div><DemoBadge/></div>
        <div className={cls('screen-panel',screen==='production'&&'active')}><Production {...value} openVoice={()=>setScreen('voices')}/></div><div className={cls('screen-panel',screen==='voices'&&'active')}><Voices {...value}/></div><div className={cls('screen-panel',screen==='clone'&&'active')}><CloneVoice {...value}/></div><div className={cls('screen-panel',screen==='tts'&&'active')}><TtsLab {...value}/></div><div className={cls('screen-panel',screen==='emotional'&&'active')}><EmotionalDirector {...value}/></div><div className={cls('screen-panel',screen==='engines'&&'active')}><Engines {...value}/></div><div className={cls('screen-panel',screen==='history'&&'active')}><HistoryView {...value}/></div><div className={cls('screen-panel',screen==='settings'&&'active')}><SettingsView {...value} toggleService={toggleService} restartService={restartService} serviceAvailable={serviceAvailable} serviceDiagnostics={serviceDiagnostics} serviceDiagnosticsWarning={serviceDiagnosticsWarning} serviceFailure={serviceFailure} updateServicePreferences={updateServicePreferences} openServiceDiagnostic={(diagnostic:ServiceFailure|ServiceDiagnostic)=>setSelectedServiceDiagnostic(diagnostic)}/></div>
      </section></main>
    <ToastStack toasts={toasts} dismiss={(id)=>setToasts(t=>t.filter(x=>x.id!==id))}/>
    {diagJob&&<DiagnosticModal job={diagJob} onClose={()=>setDiagJob(null)}/>} {selectedServiceDiagnostic&&<ServiceDiagnosticModal diagnostic={selectedServiceDiagnostic} onClose={()=>setSelectedServiceDiagnostic(null)}/>} {selectedJob&&<JobDetail job={selectedJob} state={state} onClose={()=>setSelectedJob(null)} openDiag={()=>setDiagJob(selectedJob)}/>} {confirmEngine&&<EngineConfirm state={state} engineId={confirmEngine} onCancel={()=>setConfirmEngine(null)} onConfirm={()=>applyProductionEngine(confirmEngine)}/>}
  </div>;
}
function finishJob(j:GenerationJob, error?:string):GenerationJob{ if(error){return {...j,status:'error',completedAt:nowIso(),error:{summary:error,stage:'Validación demo',technicalDetail:`Diagnóstico simulado para ${j.id}. Texto original conservado: ${j.request.originalText}`},events:[...j.events,{id:`evt-${j.id}-err`,jobId:j.id,at:nowIso(),stage:'Error demo',summary:error,technicalDetail:'Evento específico del trabajo. Sin secretos ni llamadas reales.',level:'error',simulated:true}]}} return {...j,status:'completed',completedAt:nowIso(),result:{durationSec:Number((2+Math.random()*6).toFixed(1)),processingMs:Math.floor(800+Math.random()*2600),demoAudioLabel:'Audio de prueba simulado'},events:[...j.events,{id:`evt-${j.id}-ok`,jobId:j.id,at:nowIso(),stage:'Finalización',summary:'Generación simulada completada',technicalDetail:'No se creó audio real ni se llamó a un motor TTS.',level:'info',simulated:true}]}; }
function Topbar({state,toggleService,reset,openDiag,serviceAvailable,openServiceDiagnostic}:{state:AppState;toggleService:()=>void;reset:()=>void;openDiag:()=>void;serviceAvailable:boolean|null;openServiceDiagnostic:()=>void}){ const active=state.jobs.filter(j=>j.status==='queued'||j.status==='processing').length; const errors=state.jobs.filter(j=>j.status==='error').length; const status=state.settings.service.status; const busy=status==='starting'||status==='stopping'; return <header className="topbar"><div><strong>Voice Studio</strong><span>Servicio local · {state.settings.service.host}:{state.settings.service.port}</span></div><div className="top-actions"><span className={cls('pill',status==='active'?'ok':status==='error'?'danger':'muted')}><Activity size={14}/>{serviceText(status)}</span><button className="btn small" disabled={serviceAvailable!==true||busy} onClick={toggleService}>{status==='active'?<Square size={14}/>:<Play size={14}/>} {status==='active'?'Detener':busy?'Esperando…':'Iniciar'}</button>{status==='error'&&<button className="icon-btn" aria-label="Diagnóstico del servicio local" title="Ver diagnóstico del servicio" onClick={openServiceDiagnostic}><AlertTriangle size={18}/></button>}<span className="pill"><Gauge size={14}/>{active} activos</span><button className="icon-btn" title="Errores recientes" onClick={openDiag}><Bell size={18}/>{errors>0&&<b>{errors}</b>}</button><button className="btn ghost small" onClick={reset}><RefreshCw size={14}/> Restaurar demo</button></div></header> }
function serviceText(s:ApplicationSettings['service']['status']){return ({stopped:'Detenido',starting:'Iniciando',active:'Activo',stopping:'Deteniendo',error:'Error',connecting:'Conectando',unavailable:'Host no disponible'} as const)[s]}
function DemoBadge(){return <span className="demo-badge">Simulación Fase 1 · no operativo</span>}
function Card({children,className}:{children:React.ReactNode;className?:string}){return <div className={cls('card',className)}>{children}</div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function Select(props:React.SelectHTMLAttributes<HTMLSelectElement>){return <select {...props}>{props.children}</select>}
function Production(p:CommonProps&{openVoice:(id:string)=>void}){ const {state,setConfirmEngine,createJob,setDiagJob,setSelectedJob,toggleVoice,setActiveVersion,openVoice}=p; const prodEngine=getEngine(state,state.settings.production.ttsEngineId); const emotionalProfile=state.profiles.find(profile=>profile.id===state.settings.production.emotionalProfileId)??state.profiles[0]; const enabled=state.voices.filter(v=>v.enabledForStreamerBot); const pending=state.jobs.filter(j=>j.status==='queued').length; const processing=state.jobs.filter(j=>j.status==='processing').length; const lastErr=state.jobs.find(j=>j.status==='error'); return <div className="grid two"><Card><h2>Estado general</h2><div className="metric-grid production-metrics"><Metric label="Servicio" value={serviceText(state.settings.service.status)} tone={state.settings.service.status==='active'?'ok':'warn'}/><Metric label="Motor TTS" value={prodEngine.name}/><Metric label="Motor" value={engineStatus(prodEngine.status)} tone={prodEngine.status==='available'?'ok':'warn'}/><Metric label="Director" value={state.settings.production.emotionalDirectorEnabled?'Activado':'Desactivado'}/><Metric label="Perfil emocional" value={emotionalProfile.name}/><Metric label="Modo emocional" value={emotionalProfile.mode==='creative'?'Creativo':'Literal'}/><Metric label="Voces habilitadas" value={String(enabled.length)}/><Metric label="Pendientes" value={String(pending)}/><Metric label="Procesando" value={String(processing)}/><Metric label="Último error" value={lastErr?.error?.summary ?? 'Sin errores'} tone={lastErr?'danger':'ok'}/></div></Card><Card><h2>Motor TTS de producción</h2><p className="muted">Se usa para solicitudes externas simuladas. Las compatibilidades no se asocian automáticamente entre proveedores.</p><Field label="Motor por defecto"><Select value={prodEngine.id} onChange={e=>setConfirmEngine(e.target.value)}>{state.engines.map(e=><option key={e.id} value={e.id}>{e.name} · {engineStatus(e.status)}</option>)}</Select></Field><Compatibility state={state} engineId={prodEngine.id}/></Card><Card className="span"><div className="section-head"><h2>Voces disponibles para Streamer.bot</h2><button className="btn" onClick={()=>createJob('Streamer.bot demo',enabled[0]?.id??state.voices[0].id,getVersion(enabled[0]??state.voices[0],(enabled[0]??state.voices[0]).activeVersionId).id,state.settings.production.ttsEngineId,'topota: ¿¿¿???---!!! JAJAJAJAaaaáááá')}>Simular solicitud externa</button></div><VoiceTable state={state} toggleVoice={toggleVoice} setActiveVersion={setActiveVersion} openVoice={openVoice}/></Card><Card className="span"><div className="section-head"><h2>Cola de generación</h2><button className="btn danger" onClick={()=>createJob('Streamer.bot demo','voice-chiquito','chiquito-v3','local-a','chiquito: Texto de prueba para error simulado','Voz no disponible')}>Provocar error demo</button></div><JobTable jobs={state.jobs.slice(0,8)} state={state} setDiagJob={setDiagJob} setSelectedJob={setSelectedJob}/></Card></div> }
function Metric({label,value,tone}:{label:string;value:string;tone?:'ok'|'warn'|'danger'}){return <div className={cls('metric',tone)}><span>{label}</span><strong>{value}</strong></div>}
function engineStatus(s:Engine['status']){return ({available:'Disponible',not_configured:'No configurado',error:'Error',offline:'Desconectado'} as const)[s]}
function Compatibility({state,engineId}:{state:AppState;engineId:string}){ const incompatible=state.voices.filter(v=>v.enabledForStreamerBot && getVersion(v,v.activeVersionId).engineId!==engineId); return <div className={cls('compat',incompatible.length?'warn':'ok')}>{incompatible.length?<><AlertTriangle size={16}/> {incompatible.length} voz/ces activas tienen referencias de otro motor: {incompatible.map(v=>v.displayName).join(', ')}. Las solicitudes podrían fallar hasta seleccionar versiones compatibles.</>:<><CheckCircle2 size={16}/> Voces habilitadas compatibles con este motor demo.</>}</div>}
function VoiceTable({state,toggleVoice,setActiveVersion,openVoice}:{state:AppState;toggleVoice:(id:string)=>void;setActiveVersion:(v:string,ver:string)=>void;openVoice?:(id:string)=>void}){return <div className="table-wrap"><table><thead><tr><th>Voz</th><th>Motor versión activa</th><th>Versión</th><th>Estado</th><th>Streamer.bot</th>{openVoice&&<th>Ficha</th>}</tr></thead><tbody>{state.voices.map(v=>{const ver=getVersion(v,v.activeVersionId); return <tr key={v.id}><td><div className="voice-cell"><span className="avatar">{v.avatar}</span><div><strong>{v.displayName}</strong><small>{v.streamerAlias}</small></div></div></td><td>{getEngine(state,ver.engineId).name}</td><td><Select value={v.activeVersionId} onChange={e=>setActiveVersion(v.id,e.target.value)}>{v.versions.map(ver=><option key={ver.id} value={ver.id}>{ver.label} · {ver.status}</option>)}</Select></td><td><span className={cls('status',v.enabledForStreamerBot?'ok':'muted')}>{v.enabledForStreamerBot?'Habilitada':'Deshabilitada'}</span></td><td><button className={cls('switch',v.enabledForStreamerBot&&'on')} aria-label={`${v.enabledForStreamerBot?'Deshabilitar':'Habilitar'} ${v.displayName} para Streamer.bot`} onClick={()=>toggleVoice(v.id)}><span/></button></td>{openVoice&&<td><button className="btn ghost small" data-voice-record={v.id} onClick={()=>openVoice(v.id)}>Abrir ficha</button></td>}</tr>})}</tbody></table></div>}
function JobTable({jobs,state,setDiagJob,setSelectedJob}:{jobs:GenerationJob[];state:AppState;setDiagJob:(j:GenerationJob)=>void;setSelectedJob:(j:GenerationJob)=>void}){return <div className="table-wrap"><table><thead><tr><th>Orden</th><th>ID</th><th>Fecha</th><th>Origen</th><th>Voz</th><th>Modo</th><th>Texto original</th><th>Estado</th><th>Tiempo</th><th></th></tr></thead><tbody>{jobs.map(j=><tr key={j.id}><td>#{j.order}</td><td>{j.id}</td><td>{fmt(j.request.createdAt)}</td><td>{j.request.origin}</td><td>{j.snapshot.voiceName} {j.snapshot.versionLabel}<small>{j.snapshot.engineName}</small></td><td>{j.request.emotionalMode}{j.request.comparisonId&&<small>{j.request.comparisonId} · lado {j.request.comparisonSide}</small>}</td><td className="clip">{j.request.originalText}</td><td><span className={cls('status',j.status)}>{statusLabel(j.status)}</span></td><td>{j.result?.processingMs?`${j.result.processingMs} ms`:'—'}</td><td className="row-actions"><button className="btn ghost small" onClick={()=>setSelectedJob(j)}>Detalles</button>{j.status==='error'&&<button className="btn small danger" onClick={()=>setDiagJob(j)}>Ver error</button>}</td></tr>)}</tbody></table></div>}
function Voices(p:CommonProps){ const {state,toggleVoice,setActiveVersion,setState,notify,createJob}=p; const [q,setQ]=useState(''); const [filter,setFilter]=useState('all'); const [engine,setEngine]=useState('all'); const [view,setView]=useState<'cards'|'list'>('cards'); const [importOpen,setImportOpen]=useState(false); const [importName,setImportName]=useState('Voz importada demo'); const [importEngine,setImportEngine]=useState(state.settings.production.ttsEngineId); const [importRef,setImportRef]=useState('demo-reference-id'); const [importDescription,setImportDescription]=useState('Voz registrada desde una referencia externa simulada.'); const [importImageName,setImportImageName]=useState(''); const voices=state.voices.filter(v=>(v.displayName+v.streamerAlias).toLowerCase().includes(q.toLowerCase())&&(filter==='all'||(filter==='enabled')===v.enabledForStreamerBot)&&(engine==='all'||v.versions.some(ver=>ver.engineId===engine))); const addImported=()=>{ const id=`voice-import-${Date.now()}`; const safeName=importName.trim()||'Voz importada demo'; setState(s=>({...s,voices:[...s.voices,{id,displayName:safeName,streamerAlias:safeName.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'voz-importada',avatar:importImageName?'🖼️':'🎙️',description:importDescription.trim()||`Registro importado simulado con referencia ${importRef || 'sin-id'}.`,enabledForStreamerBot:false,activeVersionId:`${id}-v1`,versions:[{id:`${id}-v1`,label:'v1',createdAt:nowIso(),engineId:importEngine,externalReferenceId:importRef||`demo-external-${Date.now()}`,notes:'Importación simulada; no valida proveedor real.',status:'ready',sampleReferenceIds:[]}]}]})); setImportOpen(false); notify(`Voz importada en modo demo: ${safeName}`,'success'); } ; return <div className="stack"><Card><div className="toolbar filter-toolbar library-filters"><input aria-label="Buscar voces" placeholder="Buscar por nombre o alias" value={q} onChange={e=>setQ(e.target.value)}/><Select aria-label="Filtrar por disponibilidad" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Todas</option><option value="enabled">Habilitadas</option><option value="disabled">Deshabilitadas</option></Select><Select aria-label="Filtrar por motor" value={engine} onChange={e=>setEngine(e.target.value)}><option value="all">Todos los motores</option>{state.engines.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</Select><button className="btn ghost" onClick={()=>setView(view==='cards'?'list':'cards')}>{view==='cards'?'Vista lista':'Vista tarjetas'}</button><button className="btn" onClick={()=>setImportOpen(true)}>Importar voz demo</button></div></Card>{view==='list'?<Card><VoiceTable state={{...state,voices}} toggleVoice={toggleVoice} setActiveVersion={setActiveVersion}/></Card>:<div className="voice-grid">{voices.map(v=>{const ver=getVersion(v,v.activeVersionId);return <Card key={v.id}><div className="voice-card-head"><span className="avatar big">{v.avatar}</span><div><h2>{v.displayName}</h2><p>{v.description}</p></div></div><div className="meta"><span>{v.versions.length} versiones</span><span>{getEngine(state,ver.engineId).name}</span></div><Field label="Versión activa para Streamer.bot"><Select value={v.activeVersionId} onChange={e=>setActiveVersion(v.id,e.target.value)}>{v.versions.map(x=><option key={x.id} value={x.id}>{x.label} — {x.notes}</option>)}</Select></Field><div className="section-head"><span className={cls('status',v.enabledForStreamerBot?'ok':'muted')}>{v.enabledForStreamerBot?'Disponible externamente':'Oculta al catálogo futuro'}</span><button className={cls('switch',v.enabledForStreamerBot&&'on')} aria-label={`${v.enabledForStreamerBot?'Deshabilitar':'Habilitar'} ${v.displayName}`} onClick={()=>toggleVoice(v.id)}><span/></button></div><div className="row-actions"><button className="btn ghost" onClick={()=>createJob('Laboratorio TTS',v.id,v.activeVersionId,ver.engineId,'AAAAA---éééé%%%%')}>Probar TTS</button><button className="btn ghost" disabled title="Edición completa en fase posterior">Editar metadatos</button></div></Card>})}</div>}{importOpen&&<SimpleModal title="Importar voz existente — simulación" onClose={()=>setImportOpen(false)}><div className="grid two compact"><Field label="Nombre"><input value={importName} onChange={e=>setImportName(e.target.value)}/></Field><Field label="Motor"><Select value={importEngine} onChange={e=>setImportEngine(e.target.value)}>{state.engines.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</Select></Field><Field label="ID de referencia existente"><input value={importRef} onChange={e=>setImportRef(e.target.value)}/></Field><Field label="Imagen opcional"><input type="file" accept="image/*" onChange={e=>setImportImageName(e.target.files?.[0]?.name??'')}/>{importImageName&&<small>{importImageName} · vista previa simulada</small>}</Field><Field label="Audio de muestra opcional"><input disabled value="Selector real en fase posterior" readOnly/></Field><Field label="Descripción"><textarea value={importDescription} onChange={e=>setImportDescription(e.target.value)}/></Field></div><p className="muted">No se validan proveedores ni claves reales. Los IDs externos son ficticios y se guardan sólo en localStorage.</p><button className="btn" onClick={addImported}>Registrar importación simulada</button></SimpleModal>}</div>}
function ReferenceEditor({state,id,setId,setTranscript,remove,transcription}:{state:AppState;id:string;setId:(id:string)=>void;setTranscript:(value:string)=>void;remove:()=>void;transcription:Engine['capabilities']['transcription']}){ const ref=state.references.find(r=>r.id===id)??state.references[0]; return <div className="ref-card"><Field label="Muestra reutilizable"><Select value={ref.id} onChange={e=>setId(e.target.value)}>{state.references.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</Select></Field><div className="wave"><Play size={16}/><span style={{width:`${Math.min(95,ref.durationSec)}%`}}/></div><div className="meta"><span>{ref.durationSec}s</span><span>{ref.format}</span><span>{ref.quality}</span><span>{ref.source}</span></div>{transcription!=='unsupported'&&<Field label={`Transcripción ${transcription==='required'?'obligatoria':'opcional'}`}><textarea value={ref.transcript??''} onChange={e=>setTranscript(e.target.value)}/></Field>}<button className="btn ghost danger" onClick={remove}>Eliminar</button></div>}
function CloneVoice(p:CommonProps){ const {state,setState,notify,createJob}=p; const cloneEngines=state.engines.filter(e=>e.capabilities.operations.includes('clone')); const [kind,setKind]=useState<'new'|'version'>('version'); const [voiceId,setVoiceId]=useState(state.voices[0].id); const [name,setName]=useState('Nueva voz demo'); const [description,setDescription]=useState('Clonación simulada creada en Fase 1.'); const [language,setLanguage]=useState('es'); const [engineId,setEngineId]=useState(cloneEngines[0].id); const [referenceIds,setReferenceIds]=useState<string[]>([state.references[0].id]); const [testText,setTestText]=useState('AAAAA---éééé%%%% · JAJAJAJAaaaáááá · ¿¿¿???---!!!'); const [testVersionId,setTestVersionId]=useState('candidate'); const [cloneTestResult,setCloneTestResult]=useState(''); const engine=getEngine(state,engineId); const sourceVoice=getVoice(state,voiceId); useEffect(()=>setTestVersionId('candidate'),[voiceId]); useEffect(()=>setReferenceIds(ids=>ids.slice(0,engine.capabilities.maxReferences)),[engineId]); const addExisting=()=>setReferenceIds(ids=>ids.length>=engine.capabilities.maxReferences?ids:[...ids,state.references.find(r=>!ids.includes(r.id))?.id??state.references[0].id]); const addSyntheticReference=(source:AudioReference['source'],fileName?:string)=>{ const id=`ref-demo-${crypto.randomUUID().slice(0,8)}`; const ref:AudioReference={id,name:fileName||`${source==='recording'?'Grabación':'Archivo'} demo ${state.references.length+1}`,durationSec:Math.max(engine.capabilities.minDurationSec,Math.min(30,engine.capabilities.maxDurationSec)),format:fileName?.split('.').pop()?.toLowerCase()||'wav',transcript:engine.capabilities.transcription==='unsupported'?undefined:'Transcripción editable de demostración.',quality:'good',engineHint:engine.id,source}; setState(s=>({...s,references:[...s.references,ref]})); setReferenceIds(ids=>ids.length>=engine.capabilities.maxReferences?ids:[...ids,id]); notify(source==='recording'?'Grabación visual simulada añadida':'Archivo registrado como muestra simulada','success'); }; const references=referenceIds.map(id=>state.references.find(r=>r.id===id)).filter((r):r is AudioReference=>Boolean(r)); const invalid=references.find(r=>r.durationSec<engine.capabilities.minDurationSec||r.durationSec>engine.capabilities.maxDurationSec||(engine.capabilities.transcription==='required'&&!r.transcript)); const save=()=>{ if(referenceIds.length===0){notify('Añadí al menos una referencia antes de guardar','warning');return;} if(invalid){notify(`La muestra ${invalid.name} no cumple los requisitos declarados del motor`,'error');return;} const versionId=`${kind==='version'?voiceId:`voice-${Date.now()}`}-v${kind==='version'?sourceVoice.versions.length+1:1}`; const version={id:versionId,label:`v${kind==='version'?sourceVoice.versions.length+1:1}`,createdAt:nowIso(),engineId:engine.id,externalReferenceId:`demo-${engine.id}-${Date.now()}`,notes:'Clonación simulada; no se generó ningún modelo real.',status:'experimental' as const,sampleReferenceIds:referenceIds,language}; setState(s=>kind==='version'?({...s,voices:s.voices.map(v=>v.id===voiceId?{...v,versions:[...v.versions,version]}:v)}):({...s,voices:[...s.voices,{id:versionId.replace(/-v1$/,''),displayName:name.trim()||'Nueva voz demo',streamerAlias:(name.trim()||'nueva-voz').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-'),avatar:'🎙️',description,enabledForStreamerBot:false,activeVersionId:versionId,versions:[version]}]})); notify(kind==='version'?`Nueva ${version.label} guardada sin cambiar la versión activa`:'Voz demo guardada y deshabilitada para solicitudes externas','success'); }; const comparisonId=`CMP-${Date.now()}`; const runTest=()=>{ const isCandidate=testVersionId==='candidate'; const chosen=isCandidate?{id:`candidate-${sourceVoice.id}-${Date.now()}`,label:'Candidata sin guardar',engineId}:getVersion(sourceVoice,testVersionId); const chosenEngine=chosen.engineId; createJob('Clonación demo',sourceVoice.id,chosen.id,chosenEngine,testText,undefined,{engineParameters:defaultEngineParameters(getEngine(state,chosenEngine)),versionOverride:isCandidate?chosen:undefined}); setCloneTestResult(`Prueba añadida a la cola · ${isCandidate?'candidata sin guardar':chosen.label} · texto conservado: ${testText}`); }; const runAb=()=>{ const first=sourceVoice.versions[0]; createJob('Clonación demo',sourceVoice.id,first.id,first.engineId,testText,undefined,{comparisonSide:'A',comparisonId}); createJob('Clonación demo',sourceVoice.id,sourceVoice.activeVersionId,getVersion(sourceVoice,sourceVoice.activeVersionId).engineId,testText,undefined,{comparisonSide:'B',comparisonId}); }; return <div className="stack"><Card><div className="section-head"><h2>Crear clonación simulada</h2><DemoBadge/></div><div className="grid two compact"><Field label="Operación"><Select value={kind} onChange={e=>setKind(e.target.value as 'new'|'version')}><option value="new">Crear voz nueva</option><option value="version">Crear nueva versión</option></Select></Field>{kind==='version'?<Field label="Voz de origen"><Select value={voiceId} onChange={e=>setVoiceId(e.target.value)}>{state.voices.map(v=><option key={v.id} value={v.id}>{v.displayName} · {v.versions.length} versiones</option>)}</Select></Field>:<Field label="Nombre"><input value={name} onChange={e=>setName(e.target.value)}/></Field>}<Field label="Idioma"><Select value={language} onChange={e=>setLanguage(e.target.value)}>{engine.capabilities.languages.map(l=><option key={l}>{l}</option>)}</Select></Field><Field label="Motor de clonación"><Select value={engineId} onChange={e=>setEngineId(e.target.value)}>{cloneEngines.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</Select></Field>{kind==='new'&&<Field label="Descripción"><textarea value={description} onChange={e=>setDescription(e.target.value)}/></Field>}</div><div className="compat"><Database size={16}/> {engine.name}: {engine.capabilities.minDurationSec}–{engine.capabilities.maxDurationSec}s, máximo {engine.capabilities.maxReferences} referencia(s), transcripción {engine.capabilities.transcription}. Idioma elegido: {language}.</div></Card><Card><div className="section-head"><h2>Referencias de audio</h2><span className="pill">{referenceIds.length}/{engine.capabilities.maxReferences}</span></div><div className="toolbar"><button className="btn" disabled={referenceIds.length>=engine.capabilities.maxReferences} onClick={addExisting}><BookOpen size={16}/> Biblioteca de muestras</button><label className={cls('btn',referenceIds.length>=engine.capabilities.maxReferences&&'disabled')}><input className="visually-hidden" type="file" accept="audio/*" disabled={referenceIds.length>=engine.capabilities.maxReferences} onChange={e=>{const file=e.target.files?.[0];if(file)addSyntheticReference('upload',file.name);e.currentTarget.value='';}}/>Subir audio</label><button className="btn" disabled={referenceIds.length>=engine.capabilities.maxReferences} onClick={()=>addSyntheticReference('recording')}><Mic size={16}/> Simular grabación</button></div><div className="ref-grid">{referenceIds.map((id,index)=><ReferenceEditor key={`${id}-${index}`} state={state} id={id} setId={next=>setReferenceIds(ids=>ids.map((x,i)=>i===index?next:x))} setTranscript={value=>setState(s=>({...s,references:s.references.map(r=>r.id===id?{...r,transcript:value}:r)}))} remove={()=>setReferenceIds(ids=>ids.filter((_,i)=>i!==index))} transcription={engine.capabilities.transcription}/>)}</div>{referenceIds.length===0&&<p className="muted">Añadí una muestra desde la biblioteca, una subida o la grabación visual simulada.</p>}<button className="btn primary" onClick={save}>Guardar {kind==='version'?'nueva versión':'voz demo'}</button><p className="muted">Las versiones anteriores se conservan. Una versión nueva no se activa automáticamente para Streamer.bot.</p></Card><Card><h2>Pruebas integradas simuladas</h2><Field label="Versión para la prueba"><Select value={testVersionId} onChange={e=>setTestVersionId(e.target.value)}><option value="candidate">Candidata actual sin guardar</option>{sourceVoice.versions.map(version=><option key={version.id} value={version.id}>{version.label} · {getEngine(state,version.engineId).name}</option>)}</Select></Field><Field label="Texto original de prueba"><textarea value={testText} onChange={e=>setTestText(e.target.value)}/></Field><div className="toolbar"><button className="btn" onClick={runTest}>Generar prueba</button><button className="btn ghost" onClick={runAb}>Comparación A/B rápida</button></div><div className="fake-player" data-clone-result><Play size={16}/>{cloneTestResult||'Resultado de prueba pendiente · no se genera audio real'}</div><p className="muted">La comparación usa exactamente el mismo texto en ambos lados y no modifica la configuración de producción.</p></Card></div>}
function TtsLab(p:CommonProps){ const {state,setState,setSelectedJob,createJob}=p; const [voiceA,setVoiceA]=useState(state.voices[0].id); const [versionA,setVersionA]=useState(getVoice(state,voiceA).activeVersionId); const [engineA,setEngineA]=useState(state.settings.production.ttsEngineId); const [paramsA,setParamsA]=useState<Record<string,string|number|boolean>>(defaultEngineParameters(getEngine(state,engineA))); const [modeA,setModeA]=useState<EmotionalMode>('literal'); const [directorA,setDirectorA]=useState(state.settings.production.emotionalDirectorEnabled); const [text,setText]=useState('AAAAA---éééé%%%%\nJAJAJAJAaaaáááá\n¿¿¿???---!!!'); const [ab,setAb]=useState(false); const [voiceB,setVoiceB]=useState(state.voices[1].id); const [versionB,setVersionB]=useState(getVoice(state,voiceB).activeVersionId); const [engineB,setEngineB]=useState(state.engines[1]?.id??state.settings.production.ttsEngineId); const [paramsB,setParamsB]=useState<Record<string,string|number|boolean>>(defaultEngineParameters(getEngine(state,engineB))); const [modeB,setModeB]=useState<EmotionalMode>('creative'); const [directorB,setDirectorB]=useState(false); const voice=getVoice(state,voiceA); const voiceBObj=getVoice(state,voiceB); useEffect(()=>{ if(!voice.versions.some(v=>v.id===versionA)) setVersionA(voice.activeVersionId);},[voiceA]); useEffect(()=>{ if(!voiceBObj.versions.some(v=>v.id===versionB)) setVersionB(voiceBObj.activeVersionId);},[voiceB]); useEffect(()=>setParamsA(defaultEngineParameters(getEngine(state,engineA))),[engineA]); useEffect(()=>setParamsB(defaultEngineParameters(getEngine(state,engineB))),[engineB]); const runA=(comparisonId?:string)=>createJob('Laboratorio TTS',voiceA,versionA,engineA,text,undefined,{emotionalMode:modeA,emotionalDirectorEnabled:directorA,engineParameters:paramsA,comparisonSide:comparisonId?'A':undefined,comparisonId}); const runB=(comparisonId:string)=>createJob('Laboratorio TTS',voiceB,versionB,engineB,text,undefined,{emotionalMode:modeB,emotionalDirectorEnabled:directorB,engineParameters:paramsB,comparisonSide:'B',comparisonId}); const runComparison=()=>{const comparisonId=`CMP-${crypto.randomUUID().slice(0,8).toUpperCase()}`;runA(comparisonId);runB(comparisonId);}; return <div className="stack"><Card><div className="section-head"><h2>Configuración de generación</h2><label className="inline-check"><input type="checkbox" checked={ab} onChange={e=>setAb(e.target.checked)}/> Comparación A/B</label></div><div className="grid two compact"><Field label="Voz"><Select value={voiceA} onChange={e=>setVoiceA(e.target.value)}>{state.voices.map(v=><option key={v.id} value={v.id}>{v.displayName}</option>)}</Select></Field><Field label="Versión"><Select value={versionA} onChange={e=>setVersionA(e.target.value)}>{voice.versions.map(v=><option key={v.id} value={v.id}>{v.label}</option>)}</Select></Field><Field label="Motor TTS"><Select value={engineA} onChange={e=>setEngineA(e.target.value)}>{state.engines.filter(e=>e.capabilities.operations.includes('tts')).map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</Select></Field><Field label="Modo de interpretación"><Select value={modeA} onChange={e=>setModeA(e.target.value as EmotionalMode)}><option value="literal">Literal — no modifica caracteres</option><option value="creative">Creativo — actuación sin reescritura automática</option><option value="minimal_rewrite_experimental" disabled>Reescritura mínima experimental (desactivada)</option></Select></Field></div><label className="inline-check"><input type="checkbox" checked={directorA} onChange={e=>setDirectorA(e.target.checked)}/> Usar director emocional en esta generación</label><Field label="Texto original inmutable"><textarea className="big-text" value={text} onChange={e=>setText(e.target.value)} /></Field><p className="muted">{text.length} caracteres. El texto se conserva íntegro en la solicitud y el historial; no se normaliza ni corrige.</p><EngineParams engine={getEngine(state,engineA)} values={paramsA} onChange={setParamsA}/><button className="btn primary" onClick={()=>ab?runComparison():runA()}>{ab?'Generar A/B simulado':'Generar simulación'}</button></Card>{ab&&<Card><h2>Comparación A/B — mismo texto original</h2><div className="ab-grid"><AbColumn title="A" state={state} voiceId={voiceA} setVoice={setVoiceA} versionId={versionA} setVersion={setVersionA} engineId={engineA} setEngine={setEngineA} mode={modeA} setMode={setModeA} director={directorA} setDirector={setDirectorA}/><AbColumn title="B" state={state} voiceId={voiceB} setVoice={setVoiceB} versionId={versionB} setVersion={setVersionB} engineId={engineB} setEngine={setEngineB} mode={modeB} setMode={setModeB} director={directorB} setDirector={setDirectorB}/></div><EngineParams engine={getEngine(state,engineB)} values={paramsB} onChange={setParamsB}/><p className="muted">Ambas columnas comparten exactamente el texto original mostrado arriba; cada solicitud conserva sus parámetros seleccionados.</p></Card>}<ResultPanel jobs={state.jobs.filter(j=>j.request.origin==='Laboratorio TTS').slice(0,3)} setState={setState} setSelectedJob={setSelectedJob}/></div>}
function EngineParams({engine,values,onChange}:{engine:Engine;values:Record<string,string|number|boolean>;onChange:(v:Record<string,string|number|boolean>)=>void}){ const setValue=(key:string,value:string|number|boolean)=>onChange({...values,[key]:value}); return <div className="param-grid">{engine.capabilities.dynamicSettings.map(s=><Field key={s.key} label={s.label}>{s.type==='range'?<input aria-label={s.label} type="range" min={s.min} max={s.max} value={Number(values[s.key]??s.defaultValue)} step="0.1" onChange={e=>setValue(s.key,Number(e.target.value))}/>:s.type==='toggle'?<input aria-label={s.label} type="checkbox" checked={Boolean(values[s.key]??s.defaultValue)} onChange={e=>setValue(s.key,e.target.checked)}/>:s.type==='select'?<Select aria-label={s.label} value={String(values[s.key]??s.defaultValue)} onChange={e=>setValue(s.key,e.target.value)}>{s.options?.map(o=><option key={o}>{o}</option>)}</Select>:<input aria-label={s.label} value={String(values[s.key]??s.defaultValue)} onChange={e=>setValue(s.key,e.target.value)}/>}</Field>)}</div>}
function AbColumn({title,state,voiceId,setVoice,versionId,setVersion,engineId,setEngine,mode,setMode,director,setDirector}:{title:string;state:AppState;voiceId:string;setVoice:(v:string)=>void;versionId:string;setVersion:(v:string)=>void;engineId:string;setEngine:(e:string)=>void;mode:EmotionalMode;setMode:(mode:EmotionalMode)=>void;director:boolean;setDirector:(enabled:boolean)=>void}){const v=getVoice(state,voiceId);return <div className="ab-col"><h3>Configuración {title}</h3><Field label="Voz"><Select value={voiceId} onChange={e=>setVoice(e.target.value)}>{state.voices.map(v=><option key={v.id} value={v.id}>{v.displayName}</option>)}</Select></Field><Field label="Versión"><Select value={versionId} onChange={e=>setVersion(e.target.value)}>{v.versions.map(x=><option key={x.id} value={x.id}>{x.label}</option>)}</Select></Field><Field label="Motor"><Select value={engineId} onChange={e=>setEngine(e.target.value)}>{state.engines.filter(e=>e.capabilities.operations.includes('tts')).map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</Select></Field><Field label="Modo de interpretación"><Select value={mode} onChange={e=>setMode(e.target.value as EmotionalMode)}><option value="literal">Literal</option><option value="creative">Creativo</option></Select></Field><label className="inline-check"><input type="checkbox" checked={director} onChange={e=>setDirector(e.target.checked)}/> Director emocional</label><div className="fake-player"><PauseCircle/> Resultado independiente simulado para lado {title}</div><Field label="Valoración manual"><Select><option>Sin valorar</option><option>Mejor naturalidad</option><option>Mejor fidelidad</option></Select></Field></div>}
function ResultPanel({jobs,setState,setSelectedJob}:{jobs:GenerationJob[];setState:React.Dispatch<React.SetStateAction<AppState>>;setSelectedJob:(job:GenerationJob)=>void}){ const save=(id:string)=>setState(s=>({...s,jobs:s.jobs.map(job=>job.id===id&&job.result?{...job,result:{...job.result,saved:true}}:job)})); return <Card><h2>Resultados recientes</h2>{jobs.length===0?<p className="muted">Todavía no hay generaciones de laboratorio.</p>:jobs.map(j=><div className="result" key={j.id}><span className={cls('status',j.status)}>{statusLabel(j.status)}</span><strong>{j.snapshot.voiceName} {j.snapshot.versionLabel}</strong><span>{j.snapshot.engineName}</span><span>Modo: {j.request.emotionalMode} · Director: {j.request.emotionalDirectorEnabled?'sí':'no'}</span><span>Duración: {j.result?.durationSec??'—'} s · Tiempo: {j.result?.processingMs??'—'} ms</span><div className="fake-player"><Play size={16}/> {j.result?.demoAudioLabel??'Esperando resultado demo'}</div><div className="row-actions"><button className="btn ghost small" disabled={!j.result||j.result.saved} onClick={()=>save(j.id)}>{j.result?.saved?'Guardado demo':'Guardar demo'}</button><button className="btn ghost small" onClick={()=>setSelectedJob(j)}>Detalles</button></div></div>)}</Card>}
function EmotionalDirector(p:CommonProps){ const {state,setState,notify,createJob}=p; const [text,setText]=useState('¡NO ME JODAS! JAJAJAJA. ¡Pero si lo tenía controlado!'); const [engineId,setEngineId]=useState(state.settings.production.ttsEngineId); const [mode,setMode]=useState<EmotionalMode>('creative'); const [profileId,setProfileId]=useState(state.settings.production.emotionalProfileId); const [freedom,setFreedom]=useState(state.profiles.find(x=>x.id===profileId)?.freedom??55); const [manualPlan,setManualPlan]=useState('Primera frase: sorpresa intensa.\nSegunda parte: carcajada marcada.\nÚltima frase: indignación cómica con pausa breve.'); const plan=makePlan(text,mode,getEngine(state,engineId),freedom,manualPlan); const directorEnabled=state.settings.production.emotionalDirectorEnabled; return <div className="grid two"><Card><h2>Configuración del director</h2><label className="inline-check"><input type="checkbox" checked={state.settings.production.emotionalDirectorEnabled} onChange={e=>setState(s=>({...s,settings:{...s.settings,production:{...s.settings.production,emotionalDirectorEnabled:e.target.checked}}}))}/> Activar director emocional en producción</label><Field label="Modelo/proveedor simulado"><Select data-director-option disabled={!directorEnabled} value={profileId} onChange={e=>{const next=e.target.value;const profile=state.profiles.find(x=>x.id===next);setProfileId(next);setFreedom(profile?.freedom??55);setState(s=>({...s,settings:{...s.settings,production:{...s.settings.production,emotionalProfileId:next}}}));}}>{state.profiles.map(profile=><option key={profile.id} value={profile.id}>{profile.name} · {profile.provider}</option>)}</Select></Field><Field label="Modo"><Select data-director-option disabled={!directorEnabled} value={mode} onChange={e=>setMode(e.target.value as EmotionalMode)}><option value="literal">Literal</option><option value="creative">Creativo</option></Select></Field><Field label={`Libertad expresiva · ${freedom}%`}><input data-director-option disabled={!directorEnabled} type="range" min="0" max="100" value={freedom} onChange={e=>setFreedom(Number(e.target.value))}/></Field><p className="muted">{directorEnabled?'La reescritura mínima queda separada y desactivada por defecto.':'Director desactivado: opciones de interpretación bloqueadas hasta volver a activarlo.'}</p></Card><Card><h2>Compatibilidad con motor</h2><Field label="Motor destino"><Select data-director-option disabled={!directorEnabled} value={engineId} onChange={e=>setEngineId(e.target.value)}>{state.engines.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</Select></Field><CompatibilityTags engine={getEngine(state,engineId)} plan={plan}/></Card><Card className="span"><h2>Visualizador de interpretación</h2><Field label="Texto original"><textarea className="big-text" value={text} onChange={e=>setText(e.target.value)}/></Field><div className="flow"><Panel title="Texto original" lines={[text]}/><ChevronRight/><Panel title="Plan emocional simulado" lines={plan.steps}/><ChevronRight/><Panel title="Instrucciones adaptadas" lines={plan.adaptedInstructions.concat(plan.unsupported.map(u=>`No compatible: ${u}`))}/></div><Field label="Edición manual de pruebas"><textarea data-director-option disabled={!directorEnabled} value={manualPlan} onChange={e=>setManualPlan(e.target.value)}/></Field><button className="btn" data-director-option disabled={!directorEnabled} onClick={()=>{createJob('Director emocional','voice-topota','topota-v2',engineId,text,undefined,{emotionalMode:mode,emotionalProfileId:profileId,interpretationPlanId:plan.id,engineParameters:{freedom,manualPlan}}); notify('Prueba con interpretación manual enviada a cola demo','info')}}>Generar prueba simulada</button></Card></div>}
function makePlan(originalText:string,mode:EmotionalMode,engine:Engine,freedom:number,manualPlan:string):InterpretationPlan{ const desired=['surprise','laugh','anger','pause','emphasis']; const unsupported=desired.filter(x=>!engine.capabilities.emotionalTags.includes(x)); const steps=manualPlan.split('\n').map(x=>x.trim()).filter(Boolean); return {id:`plan-${engine.id}-${mode}-${freedom}`,originalText,mode,engineId:engine.id,simulated:true,steps:steps.length?steps:['Sin instrucciones manuales.'],adaptedInstructions:desired.filter(x=>engine.capabilities.emotionalTags.includes(x)).map(x=>`Usar recurso compatible: ${x} · libertad ${freedom}%`),unsupported}; }
function Panel({title,lines}:{title:string;lines:string[]}){return <div className="flow-panel"><h3>{title}</h3>{lines.map((l,i)=><p key={i}>{l}</p>)}</div>}
function CompatibilityTags({engine,plan}:{engine:Engine;plan:InterpretationPlan}){return <div><div className="tag-row">{engine.capabilities.emotionalTags.map(t=><span className="tag" key={t}>{t}</span>)}</div>{plan.unsupported.length>0&&<div className="compat warn"><AlertTriangle size={16}/> Recursos no compatibles: {plan.unsupported.join(', ')}. No se enviarían literalmente a este motor.</div>}</div>}
function Engines({state}:CommonProps){ const [selected,setSelected]=useState(state.engines[0].id); const engine=getEngine(state,selected); return <div className="grid engines-layout"><Card><h2>Catálogo de motores</h2>{state.engines.map(e=><button key={e.id} className={cls('engine-row',selected===e.id&&'active')} onClick={()=>setSelected(e.id)}><strong>{e.name}</strong><span>{e.kind} · {e.locality} · {engineStatus(e.status)}</span></button>)}</Card><Card><h2>{engine.name}</h2><p>{engine.description}</p><div className="metric-grid"><Metric label="Tipo" value={engine.kind}/><Metric label="Localidad" value={engine.locality}/><Metric label="Estado" value={engineStatus(engine.status)} tone={engine.status==='available'?'ok':'warn'}/><Metric label="Versión" value={engine.version}/></div><h3>Capacidades declaradas</h3><ul className="cap-list"><li>Operaciones: {engine.capabilities.operations.join(', ')}</li><li>Referencias: {engine.capabilities.maxReferences}</li><li>Idiomas: {engine.capabilities.languages.join(', ')}</li><li>Etiquetas: {engine.capabilities.emotionalTags.join(', ')||'ninguna'}</li><li>Controles: {engine.capabilities.controls.join(', ')}</li><li>Formatos: {engine.capabilities.audioFormats.join(', ')}</li>{engine.capabilities.limitations.map(l=><li key={l}>{l}</li>)}</ul><h3>Configuración futura</h3><div className="grid two compact">{engine.configFields.map(f=><Field key={f.key} label={f.label}><input type={f.type==='password'?'password':'text'} placeholder={f.placeholder} disabled={f.futureOnly}/></Field>)}</div><p className="muted">No guardes secretos reales: todos los campos sensibles están deshabilitados en Fase 1.</p></Card></div>}
function HistoryView(p:CommonProps){ const {state,setDiagJob,setSelectedJob}=p; const [status,setStatus]=useState('all'); const [origin,setOrigin]=useState('all'); const [voice,setVoice]=useState('all'); const [date,setDate]=useState(''); const jobs=state.jobs.filter(j=>(status==='all'||j.status===status)&&(origin==='all'||j.request.origin===origin)&&(voice==='all'||j.request.voiceId===voice)&&(!date||j.request.createdAt.slice(0,10)===date)); return <div className="stack"><Card><div className="toolbar filter-toolbar history-filters"><Field label="Fecha"><input type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="Estado"><Select aria-label="Filtrar por estado" value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Todos los estados</option><option value="completed">Completada</option><option value="error">Error</option><option value="queued">En cola</option><option value="processing">Procesando</option><option value="cancelled">Cancelada</option></Select></Field><Field label="Origen"><Select aria-label="Filtrar por origen" value={origin} onChange={e=>setOrigin(e.target.value)}><option value="all">Todos los orígenes</option><option>Streamer.bot demo</option><option>Laboratorio TTS</option><option>Clonación demo</option><option>Director emocional</option></Select></Field><Field label="Voz"><Select aria-label="Filtrar por voz" value={voice} onChange={e=>setVoice(e.target.value)}><option value="all">Todas las voces</option>{state.voices.map(v=><option key={v.id} value={v.id}>{v.displayName}</option>)}</Select></Field></div></Card><Card><JobTable jobs={jobs} state={state} setDiagJob={setDiagJob} setSelectedJob={setSelectedJob}/></Card></div>}
type SettingsViewProps = CommonProps & { toggleService:()=>void; restartService:()=>void; serviceAvailable:boolean|null; serviceDiagnostics:ServiceDiagnostic[]; serviceDiagnosticsWarning:string|null; serviceFailure:ServiceFailure|null; updateServicePreferences:(change:Partial<ServicePreferences>)=>Promise<void>; openServiceDiagnostic:(diagnostic:ServiceFailure|ServiceDiagnostic)=>void };
function SettingsView(p:SettingsViewProps){ const {state,setState,toggleService,restartService,serviceAvailable,serviceDiagnostics,serviceDiagnosticsWarning,serviceFailure,updateServicePreferences,openServiceDiagnostic}=p; const s=state.settings; const service=s.service; const [portDraft,setPortDraft]=useState(String(service.port)); useEffect(()=>setPortDraft(String(service.port)),[service.port]); const patch=(settings:ApplicationSettings)=>setState(st=>({...st,settings})); const updateService=(change:Partial<ServicePreferences>)=>updateServicePreferences(change); const busy=service.status==='starting'||service.status==='stopping'; return <div className="grid two"><Card><h2>Servicio local</h2><div className="metric-grid"><Metric label="Estado efectivo" value={serviceText(service.status)} tone={service.status==='active'?'ok':service.status==='error'?'danger':'warn'}/><Metric label="Dirección de escucha" value={`${service.host}:${service.port}`}/></div><p className="muted">El servicio sólo escucha en 127.0.0.1. Las voces y los trabajos de esta demo no se envían al servicio.</p><div className="grid two compact"><Field label="Puerto del servicio"><input aria-label="Puerto del servicio" type="number" min="1024" max="65535" value={portDraft} onChange={e=>setPortDraft(e.target.value)}/></Field><div className="field"><span>Aplicar</span><button className="btn" disabled={serviceAvailable!==true} onClick={()=>updateService({port:Number(portDraft)})}>Aplicar puerto</button></div></div><div className="toolbar"><button className="btn" disabled={serviceAvailable!==true||busy} onClick={toggleService}>{service.status==='active'?'Detener':'Iniciar'}</button><button className="btn ghost" disabled={serviceAvailable!==true||busy} onClick={restartService}>Reiniciar</button></div><label className="inline-check"><input type="checkbox" checked={service.autoStart} disabled={serviceAvailable!==true} onChange={e=>void updateService({autoStart:e.target.checked})}/> Iniciar servicio automáticamente al abrir la aplicación</label><label className="inline-check"><input type="checkbox" checked={service.keepRunningOnClose} disabled={serviceAvailable!==true} onChange={e=>void updateService({keepRunningOnClose:e.target.checked})}/> Mantener servicio al cerrar la interfaz</label>{serviceAvailable===false&&<p role="status" className="compat warn">Host de escritorio no disponible; abrí esta interfaz desde Voice Studio.</p>}</Card><Card><h2>Configuración general</h2><Field label="Carpeta de almacenamiento"><input value={s.general.storageFolder} onChange={e=>patch({...s,general:{...s.general,storageFolder:e.target.value}})}/></Field><Field label="Preferencia de audio"><input value={s.general.audioOutput} onChange={e=>patch({...s,general:{...s.general,audioOutput:e.target.value}})}/></Field><Field label="Retención de historial (días)"><input type="number" value={s.general.historyRetentionDays} onChange={e=>patch({...s,general:{...s.general,historyRetentionDays:Number(e.target.value)}})}/></Field><label className="inline-check"><input type="checkbox" checked={s.general.diagnosticsVerbose} onChange={e=>patch({...s,general:{...s.general,diagnosticsVerbose:e.target.checked}})}/> Diagnóstico detallado</label></Card><Card className="span"><div className="section-head"><h2>Diagnósticos del servicio</h2>{serviceFailure&&<button className="btn ghost small" onClick={()=>openServiceDiagnostic(serviceFailure)}>Ver último fallo</button>}</div>{serviceDiagnosticsWarning&&<p role="status" className="compat warn">No se pudieron obtener los diagnósticos del servicio: {serviceDiagnosticsWarning}</p>}{serviceDiagnostics.length===0&&!serviceDiagnosticsWarning?<p className="muted">No hay fallos registrados por el servicio local.</p>:serviceDiagnostics.length>0&&<ul className="service-diagnostics">{serviceDiagnostics.slice(0,8).map(item=><li key={item.id}><button className="btn ghost small" onClick={()=>openServiceDiagnostic(item)}>{fmt(item.at)} · {item.code} · {item.summary}</button></li>)}</ul>}</Card></div>}
function DiagnosticModal({job,onClose}:{job:GenerationJob;onClose:()=>void}){ const text=`${job.id}\nResumen: ${job.error?.summary??'Sin error'}\nEtapa: ${job.error?.stage??'—'}\nFecha: ${fmt(job.completedAt)}\nDetalle técnico simulado: ${job.error?.technicalDetail??job.events.map(e=>e.technicalDetail).join('\n')}`; return <SimpleModal title={`Diagnóstico específico · ${job.id}`} onClose={onClose}><div className="diag"><p><strong>Resumen:</strong> {job.error?.summary??'Evento sin error'}</p><p><strong>Etapa:</strong> {job.error?.stage??'—'}</p><p><strong>Fecha y hora:</strong> {fmt(job.completedAt??job.request.createdAt)}</p><p><strong>Trabajo:</strong> {job.id}</p><details open><summary>Detalle técnico simulado</summary><pre>{job.error?.technicalDetail??job.events.map(e=>e.technicalDetail).join('\n')}</pre></details><button className="btn" onClick={()=>navigator.clipboard?.writeText(text)}><Copy size={16}/> Copiar diagnóstico</button></div></SimpleModal>}
function ServiceDiagnosticModal({diagnostic,onClose}:{diagnostic:ServiceFailure|ServiceDiagnostic;onClose:()=>void}){ const text=`${diagnostic.code}\nResumen: ${diagnostic.summary}\nFecha: ${diagnostic.at}\nDirección: ${diagnostic.host}:${diagnostic.port}\nDetalle: ${diagnostic.detail}`; return <SimpleModal title={`Diagnóstico del servicio · ${diagnostic.code}`} onClose={onClose}><div className="diag"><p><strong>Código:</strong> {diagnostic.code}</p><p><strong>Resumen:</strong> {diagnostic.summary}</p><p><strong>Fecha y hora:</strong> {fmt(diagnostic.at)}</p><p><strong>Dirección:</strong> {diagnostic.host}:{diagnostic.port}</p><details open><summary>Detalle técnico del fallo</summary><pre>{diagnostic.detail}</pre></details><button className="btn" onClick={()=>navigator.clipboard?.writeText(text)}><Copy size={16}/> Copiar diagnóstico</button></div></SimpleModal>}
function JobDetail({job,state,onClose,openDiag}:{job:GenerationJob;state:AppState;onClose:()=>void;openDiag:()=>void}){
  const elapsed=(from?:string,to?:string)=>from&&to?`${Math.max(0,new Date(to).getTime()-new Date(from).getTime())} ms`:'—';
  const profile=state.profiles.find(item=>item.id===job.request.emotionalProfileId);
  const manualPlan=job.request.engineParameters?.manualPlan;
  const plan=job.request.emotionalDirectorEnabled?(typeof manualPlan==='string'&&manualPlan?manualPlan:`Perfil ${profile?.name??job.request.emotionalProfileId??'simulado'} · modo ${job.request.emotionalMode}`):'Director emocional no utilizado en este trabajo.';
  return <SimpleModal title={`Detalle de evento · ${job.id}`} onClose={onClose}><div className="grid two compact"><Metric label="Estado" value={statusLabel(job.status)} tone={job.status==='error'?'danger':job.status==='completed'?'ok':'warn'}/><Metric label="Origen" value={job.request.origin}/><Metric label="Voz" value={`${job.snapshot.voiceName} ${job.snapshot.versionLabel}`}/><Metric label="Motor" value={job.snapshot.engineName}/></div><Field label="Entrada original"><textarea readOnly value={job.request.originalText}/></Field><h3>Configuración exacta utilizada</h3><pre className="log">{JSON.stringify(job.snapshot,null,2)}</pre><h3>Plan emocional</h3><pre className="log">{plan}</pre><h3>Resultado</h3><pre className="log">{job.result?JSON.stringify(job.result,null,2):job.error?`Sin resultado · ${job.error.summary}`:'Resultado pendiente'}</pre><h3>Duración de fases</h3><div className="metric-grid"><Metric label="Espera en cola" value={elapsed(job.request.createdAt,job.startedAt)}/><Metric label="Procesamiento" value={elapsed(job.startedAt,job.completedAt)}/></div><h3>Eventos relacionados</h3>{job.events.map(e=><div className="event" key={e.id}><span className={cls('status',e.level==='error'?'error':e.level==='warning'?'queued':'completed')}>{e.stage}</span><strong>{e.summary}</strong><small>{fmt(e.at)}</small></div>)}{job.status==='error'&&<button className="btn danger" onClick={openDiag}>Ver registro específico</button>}</SimpleModal>
}
function EngineConfirm({state,engineId,onCancel,onConfirm}:{state:AppState;engineId:string;onCancel:()=>void;onConfirm:()=>void}){ const e=getEngine(state,engineId); const incompatible=state.voices.filter(v=>v.enabledForStreamerBot && getVersion(v,v.activeVersionId).engineId!==engineId); return <SimpleModal title="Confirmar cambio de motor de producción" onClose={onCancel}><p>Cambiar a <strong>{e.name}</strong>. Esto actualiza la configuración activa simulada.</p>{incompatible.length>0&&<div className="compat warn"><AlertTriangle/> Voces potencialmente incompatibles: {incompatible.map(v=>v.displayName).join(', ')}. Una referencia de otro proveedor no se reutiliza automáticamente.</div>}<div className="toolbar"><button className="btn ghost" onClick={onCancel}>Cancelar</button><button className="btn" onClick={onConfirm}>Confirmar cambio</button></div></SimpleModal>}
function SimpleModal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){const titleId=useId();return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby={titleId} tabIndex={-1} onKeyDown={e=>{if(e.key==='Escape')onClose();}}><div className="modal"><div className="section-head modal-header"><h2 id={titleId}>{title}</h2><button className="icon-btn" aria-label="Cerrar ventana" autoFocus onClick={onClose}><X/></button></div><div className="modal-body">{children}</div></div></div>}
function ToastStack({toasts,dismiss}:{toasts:Toast[];dismiss:(id:string)=>void}){return <div className="toasts">{toasts.map(t=><button key={t.id} className={cls('toast',t.kind)} onClick={()=>dismiss(t.id)}>{t.text}</button>)}</div>}
type CommonProps = { state:AppState; setState:React.Dispatch<React.SetStateAction<AppState>>; notify:(t:string,k?:Toast['kind'])=>void; toggleVoice:(id:string)=>void; setActiveVersion:(v:string,ver:string)=>void; createJob:(origin:GenerationJob['request']['origin'],voiceId:string,versionId:string,engineId:string,text:string,forceError?:string,options?:CreateJobOptions)=>void; setDiagJob:(j:GenerationJob|null)=>void; setConfirmEngine:(id:string|null)=>void; setSelectedJob:(j:GenerationJob|null)=>void; applyProductionEngine:(id:string)=>void };
